360	/** @brief 在 OtaCommand RPC 被拒绝或断连时更新错误状态并清理失效扫描摘要。 */
361	void apply_failed_ota_rpc(const AisocOtaRequest& req, uint64_t req_seq,
362	                          int32_t rc, AisocOtaStatus* next) {
363	    if (next == nullptr) return;
364	    next->client_req_seq = req_seq;
365	    if (rc != -5 || !next->active) {
366	        next->active = false;
367	        next->reboot_verified = false;
368	        if (req.operation == 0U) {
369	            next->phase = "FAILED";
370	            next->mc = AisocOtaNodeInfo{};
371	            next->th = AisocOtaNodeInfo{};
372	        }
373	    }
374	    if (rc == -5) {
375	        next->error = "BACKEND_BUSY";
376	    } else if (rc == -100 || rc == AISOC_DBUS_ERR_DISCONNECTED || rc == -1) {
377	        next->phase = "FAILED";
378	        next->error = "RPC_DISCONNECTED";
379	    } else {
380	        next->phase = "FAILED";
381	        next->error = "OTA_COMMAND_REJECTED";
382	    }
383	}
