670	void AisocConnection::process_pending_ota() {
671	    while (true) {
672	        QueuedOtaRequest item;
673	        {
674	            std::lock_guard<std::mutex> lock(mutex_);
675	            if (stop_requested_ || ota_queue_.empty()) return;
676	            item = ota_queue_.front();
677	            ota_queue_.erase(ota_queue_.begin());
678	        }
679	        ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
680	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
681	        uint64_t task_id = 0U;
682	        const int32_t rc = execute_fwd_ota_command(conn, item.request, config_.rpc_timeout_ms, &task_id);
683	        AisocOtaStatus next;
684	        {
685	            std::lock_guard<std::mutex> lock(mutex_);
686	            next = ota_status_;
687	            next.last_rpc_code = rc;
688	            if (rc == 0) {
689	                tracked_task_id_ = std::to_string(task_id);
690	                tracked_req_seq_ = item.req_seq;
691	                tracked_ota_op_ = item.request.operation;
692	                ota_last_activity_tp_ = std::chrono::steady_clock::now();
693	                pending_reboot_verify_ = false;
694	                apply_accepted_ota_rpc(item.request, item.req_seq, tracked_task_id_, &next);
695	            } else {
696	                const int32_t eff_rc = (conn == nullptr) ? -100 : rc;
697	                if (eff_rc != -5 || !ota_status_.active) {
698	                    tracked_task_id_.clear();
699	                    tracked_req_seq_ = 0U;
700	                    pending_reboot_verify_ = false;
701	                }
702	                apply_failed_ota_rpc(item.request, item.req_seq, eff_rc, &next);
703	            }
704	        }
705	        emit_ota_status(next);
706	    }
707	}
