709	void AisocConnection::check_ota_dds_timeout() {
710	    AisocOtaStatus timed_out;
711	    bool did_timeout = false;
712	    {
713	        std::lock_guard<std::mutex> lock(mutex_);
714	        if (ota_status_.active && ota_last_activity_tp_.time_since_epoch().count() > 0) {
715	            const uint32_t limit_ms = (!tracked_task_id_.empty() && tracked_ota_op_ == 0U)
716	                ? (config_.ota_scan_timeout_ms > 0U ? config_.ota_scan_timeout_ms : 3000U)
717	                : (config_.ota_active_timeout_ms > 0U ? config_.ota_active_timeout_ms : 30000U);
718	            const auto elapsed = std::chrono::steady_clock::now() - ota_last_activity_tp_;
719	            if (elapsed >= std::chrono::milliseconds(limit_ms)) {
720	                timed_out = ota_status_;
721	                timed_out.active = false;
722	                timed_out.maintenance = false;
723	                timed_out.phase = "FAILED";
724	                timed_out.error = "OTA_DDS_TIMEOUT";
725	                timed_out.last_rpc_code = 0;
726	                timed_out.reboot_verified = false;
727	                timed_out.client_req_seq = !tracked_task_id_.empty() ? tracked_req_seq_ : 0U;
728	                timed_out.mc = AisocOtaNodeInfo{};
729	                timed_out.th = AisocOtaNodeInfo{};
730	                tracked_task_id_.clear();
731	                tracked_req_seq_ = 0U;
732	                pending_reboot_verify_ = false;
733	                did_timeout = true;
734	            }
735	        }
736	    }
737	    if (did_timeout) emit_ota_status(timed_out);
738	}
