   203	/**
   204	 * @brief 解除已确认的急停锁；正交保留锁存前及锁存期上报的独立故障并广播真实前后状态
   205	 * @param state 设备管理服务状态结构体指针
   206	 */
   207	static void clear_emergency_stop_state(device_manager_state_t* state) {
   208	    if (state == nullptr) return;
   209	    char old_state[32] = {}, new_state[32] = {};
   210	    pthread_mutex_lock(&state->state_mutex);
   211	    std::snprintf(old_state, sizeof(old_state), "%s", state->device_state);
   212	    if (state->estop_latched) {
   213	        state->is_fault = state->non_estop_fault;
   214	    } else if (state->is_fault) {
   215	        state->non_estop_fault = true;
   216	    }
   217	    state->estop_latched = false;
   218	    state->estop_confirmed = false;
   219	    std::snprintf(state->device_state, sizeof(state->device_state), "%s", state->is_fault ? "FAULT" : "IDLE");
   220	    if (state->is_fault && std::strcmp(state->snapshot.system_status_desc, "EMERGENCY_STOP_INVOKED") == 0) {
   221	        std::snprintf(state->snapshot.system_status_desc, sizeof(state->snapshot.system_status_desc), "FAULT");
   222	    }
   223	    dev_state_eval_freshness(state, get_host_monotonic_ns());
   224	    state->generation_id += 1U;
   225	    state->snapshot.generation_id = state->generation_id;
   226	    std::snprintf(new_state, sizeof(new_state), "%s", state->device_state);
   227	    pthread_mutex_unlock(&state->state_mutex);
   228	    dev_dbus_emit_state_changed(state, old_state, new_state, "Emergency stop cleared");
   229	}
