   231	/** @brief state为锁定对象；同步既有独立故障并先置本地未确认锁，下游超时仍保持本地保护。 */
   232	static void latch_emergency_stop(device_manager_state_t* state) {
   233	    if (state == nullptr) return;
   234	    char old_state[32] = {};
   235	    pthread_mutex_lock(&state->state_mutex);
   236	    if (!state->estop_latched && state->is_fault) {
   237	        state->non_estop_fault = true;
   238	    }
   239	    state->estop_latched = true;
   240	    state->estop_confirmed = false;
   241	    dev_state_set_fault(state, "EMERGENCY_STOP_INVOKED", old_state, sizeof(old_state));
   242	    state->generation_id += 1U;
   243	    state->snapshot.generation_id = state->generation_id;
   244	    pthread_mutex_unlock(&state->state_mutex);
   245	    dev_dbus_emit_state_changed(state, old_state, "FAULT", "Emergency stop requested");
   246	}
