   278	/**
   279	 * @brief 调用下游 ForwardInterface.EmergencyStop 转发急停锁存或解除请求
   280	 * @param conn D-Bus 连接指针
   281	 * @param reason_code 急停动作码（1=锁存，0=解除）
   282	 * @return int32_t 双板均应答成功返回 0，否则返回对应负错误码
   283	 */
   284	static int32_t forward_emergency_stop_rpc(aisoc_dbus_conn_t* conn, uint8_t reason_code) {
   285	    if (conn == nullptr) return AISOC_DEV_ERR_DBUS_INIT;
   286	    aisoc_dbus_method_call_t call = {
   287	        AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "EmergencyStop"
   288	    };
   289	    aisoc_dbus_msg_t fwd_req, fwd_reply;
   290	    aisoc_dbus_msg_init_call(&call, &fwd_req);
   291	    aisoc_dbus_msg_append_byte(&fwd_req, reason_code);
   292	    aisoc_dbus_call_opts_t fwd_opts = { 600, true };
   293	    const aisoc_dbus_status_t fwd_st = aisoc_dbus_call_method(conn, &fwd_req, &fwd_opts, &fwd_reply);
   294	    aisoc_dbus_msg_unref(&fwd_req);
   295	    if (fwd_st != AISOC_DBUS_OK) return (int32_t)fwd_st;
   296	    int32_t fwd_err = AISOC_DEV_ERR_FAULT;
   297	    aisoc_dbus_iter_t r_iter;
   298	    aisoc_dbus_iter_init(&fwd_reply, &r_iter);
   299	    if (aisoc_dbus_iter_get_int32(&r_iter, &fwd_err) != AISOC_DBUS_OK) fwd_err = AISOC_DEV_ERR_FAULT;
   300	    aisoc_dbus_msg_unref(&fwd_reply);
   301	    return fwd_err;
   302	}
