   304	/**
   305	 * @brief 处理 D-Bus EmergencyStop 请求：触发或清除急停锁定并转发至 ForwardService
   306	 * @param req D-Bus 请求消息指针
   307	 * @param reply D-Bus 响应消息指针
   308	 * @param user_data 用户上下文指针（指向 device_manager_state_t）
   309	 * @return aisoc_dbus_status_t 成功返回 AISOC_DBUS_OK
   310	 */
   311	static aisoc_dbus_status_t handle_emergency_stop(
   312	    const aisoc_dbus_msg_t* req,
   313	    aisoc_dbus_msg_t* reply,
   314	    void* user_data
   315	) {
   316	    if (req == nullptr || reply == nullptr || user_data == nullptr) return AISOC_DBUS_ERR_NULL_PTR;
   317	    device_manager_state_t* state = (device_manager_state_t*)user_data;
   318	    aisoc_dbus_iter_t iter;
   319	    aisoc_dbus_iter_init(req, &iter);
   320	    uint8_t reason_code = 0U;
   321	    if (aisoc_dbus_iter_get_byte(&iter, &reason_code) != AISOC_DBUS_OK || reason_code > 1U) {
   322	        aisoc_dbus_msg_append_int32(reply, AISOC_DEV_ERR_INVALID_ARG);
   323	        return AISOC_DBUS_OK;
   324	    }
   325	    pthread_mutex_lock(&state->state_mutex);
   326	    const bool in_maint = state->is_maintenance || state->ota_recovery_pending;
   327	    const bool prev_latched = state->estop_latched;
   328	    pthread_mutex_unlock(&state->state_mutex);
   329	    if (in_maint) {
   330	        aisoc_dbus_msg_append_int32(reply, AISOC_DEV_ERR_BUSY);
   331	        return AISOC_DBUS_OK;
   332	    }
   333	    const auto policy = reason_code == 0U ? dev_control_policy::CLEAR : dev_control_policy::STOP;
   334	    const int32_t admission = control_permission(state, 3U, policy);
   335	    if (admission != 0) {
   336	        aisoc_dbus_msg_append_int32(reply, admission);
   337	        return AISOC_DBUS_OK;
   338	    }
   339	    if (reason_code == 1U) latch_emergency_stop(state);
   340	    else unconfirm_emergency_stop(state);
   341	
   342	    const int32_t fwd_err = forward_emergency_stop_rpc(&state->dbus_conn, reason_code);
   343	    if (reason_code == 1U && fwd_err == 0) confirm_emergency_stop(state);
   344	    else if (reason_code == 1U && fwd_err == AISOC_DEV_ERR_BUSY && !prev_latched) clear_emergency_stop_state(state);
   345	    if (reason_code == 0U && fwd_err == 0) clear_emergency_stop_state(state);
   346	    aisoc_dbus_msg_append_int32(reply, fwd_err);
   347	    return AISOC_DBUS_OK;
   348	}
