588	uint32_t AisocConnection::compute_worker_wait_ms() const {
589	    uint32_t wait_ms = config_.poll_interval_ms > 0U ? config_.poll_interval_ms : 1000U;
590	    if ((ota_status_.active || pending_reboot_verify_) && wait_ms > 80U) wait_ms = 80U;
591	    if (ota_status_.active && ota_last_activity_tp_.time_since_epoch().count() > 0) {
592	        const uint32_t limit_ms = (!tracked_task_id_.empty() && tracked_ota_op_ == 0U)
593	            ? (config_.ota_scan_timeout_ms > 0U ? config_.ota_scan_timeout_ms : 3000U)
594	            : (config_.ota_active_timeout_ms > 0U ? config_.ota_active_timeout_ms : 30000U);
595	        const auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
596	            std::chrono::steady_clock::now() - ota_last_activity_tp_).count();
597	        const uint32_t rem_ms = (elapsed_ms >= static_cast<int64_t>(limit_ms))
598	            ? 5U : static_cast<uint32_t>(static_cast<int64_t>(limit_ms) - elapsed_ms);
599	        if (rem_ms < wait_ms) wait_ms = rem_ms > 5U ? rem_ms : 5U;
600	    }
601	    return wait_ms;
602	}
