629	void AisocConnection::process_pending_estops() {
630	    while (true) {
631	        bool engage = true;
632	        EstopCallback cb;
633	        {
634	            std::lock_guard<std::mutex> lock(mutex_);
635	            if (stop_requested_ || estop_queue_.empty()) return;
636	            engage = estop_queue_.front();
637	            estop_queue_.erase(estop_queue_.begin());
638	            cb = estop_cb_;
639	        }
640	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
641	        const AisocEstopResult res = execute_dm_estop(conn, engage, config_.rpc_timeout_ms);
642	        if (res.outcome == AisocEstopOutcome::DISCONNECTED) close_dbus(&dbus_handle_);
643	        AisocSnapshot updated;
644	        AisocOtaStatus ota_snap;
645	        OtaStatusCallback ota_cb;
646	        {
647	            std::lock_guard<std::mutex> lock(mutex_);
648	            if (res.outcome == AisocEstopOutcome::CONFIRMED) {
649	                snapshot_.estop_latched = engage;
650	                snapshot_.estop_confirmed = engage;
651	            } else if (res.outcome == AisocEstopOutcome::DISCONNECTED) {
652	                snapshot_.estop_latched = false;
653	                snapshot_.estop_confirmed = false;
654	            } else if (res.outcome == AisocEstopOutcome::FAILED) {
655	                snapshot_.estop_confirmed = false;
656	                refresh_requested_ = true;
657	            }
658	            snapshot_.last_estop_outcome = res.outcome;
659	            snapshot_.last_estop_detail = res.detail;
660	            updated = snapshot_;
661	            ota_snap = ota_status_;
662	            ota_cb = ota_cb_;
663	        }
664	        publish_if_changed(updated, true);
665	        if (ota_cb) ota_cb(ota_snap);
666	        if (cb) cb(res);
667	    }
668	}
