740	void AisocConnection::poll_ota_dds() {
741	    auto* sub = ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
742	    if (sub == nullptr) return;
743	    aisoc_ota_status_t sample = {};
744	    for (uint32_t i = 0U; i < 32U; ++i) {
745	        if (aisoc_dds_take_ota_status(sub, &sample) != AISOC_DDS_OK) break;
746	        AisocOtaStatus parsed;
747	        if (!parse_ota_status_json(sample.json, &parsed)) continue;
748	        bool accept = false;
749	        {
750	            std::lock_guard<std::mutex> lock(mutex_);
751	            if (should_accept_ota_sample(ota_status_, tracked_task_id_, parsed)) {
752	                accept = true;
753	                const bool matched_tracked = (!tracked_task_id_.empty() && parsed.task_id == tracked_task_id_);
754	                parsed.client_req_seq = matched_tracked ? tracked_req_seq_ : 0U;
755	                if (!matched_tracked || !parsed.active) {
756	                    tracked_task_id_.clear();
757	                    tracked_req_seq_ = 0U;
758	                }
759	                if (parsed.active) ota_last_activity_tp_ = std::chrono::steady_clock::now();
760	                parsed.last_rpc_code = 0;
761	                parsed.reboot_verified = false;
762	                pending_reboot_verify_ = (parsed.phase == "SUCCEEDED");
763	            }
764	        }
765	        if (accept) emit_ota_status(parsed);
766	    }
767	    check_ota_dds_timeout();
768	}
