770	void AisocConnection::verify_pending_ota_reboot(const McuNodeInfo& dm_mc, const McuNodeInfo& dm_th) {
771	    AisocOtaStatus verified;
772	    bool newly_verified = false;
773	    {
774	        std::lock_guard<std::mutex> lock(mutex_);
775	        if (!pending_reboot_verify_ || ota_status_.phase != "SUCCEEDED") return;
776	        const uint32_t mask = ota_status_.target_mask;
777	        if (mask == 0U) return;
778	        const bool mc_ok = ((mask & 1U) == 0U) || node_reboot_verified(dm_mc, ota_status_.mc.pre_boot_id);
779	        const bool th_ok = ((mask & 2U) == 0U) || node_reboot_verified(dm_th, ota_status_.th.pre_boot_id);
780	        if (mc_ok && th_ok) {
781	            pending_reboot_verify_ = false;
782	            ota_status_.reboot_verified = true;
783	            verified = ota_status_;
784	            newly_verified = true;
785	        }
786	    }
787	    if (newly_verified) emit_ota_status(verified);
788	}
