790	void AisocConnection::poll_once() {
791	    AisocSnapshot next;
792	    {
793	        std::lock_guard<std::mutex> lock(mutex_);
794	        next.ap = snapshot_.ap;
795	        next.estop_latched = snapshot_.estop_latched;
796	        next.estop_confirmed = snapshot_.estop_confirmed;
797	        next.last_estop_outcome = snapshot_.last_estop_outcome;
798	        next.last_estop_detail = snapshot_.last_estop_detail;
799	    }
800	    auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
801	    if (conn == nullptr) {
802	        next.estop_latched = false;
803	        next.estop_confirmed = false;
804	        next.device_state = "OFFLINE";
805	        next.system_status = "OFFLINE";
806	        publish_if_changed(next, false);
807	        return;
808	    }
809	    std::string ver_json;
810	    const aisoc_dbus_status_t ver_st = call_dm_string(conn, "GetVersionInfo", config_.rpc_timeout_ms, &ver_json);
811	    if (ver_st != AISOC_DBUS_OK || !parse_dm_version_json(ver_json, &next.mc, &next.th)) {
812	        if (ver_st == AISOC_DBUS_ERR_DISCONNECTED) close_dbus(&dbus_handle_);
813	        next.dm_connected = false;
814	        next.estop_latched = false;
815	        next.estop_confirmed = false;
816	        next.device_state = "OFFLINE";
817	        next.system_status = "OFFLINE";
818	        publish_if_changed(next, false);
819	        return;
820	    }
821	    next.dm_connected = true;
822	    verify_pending_ota_reboot(next.mc, next.th);
823	    std::string snap_json, state_json;
824	    if (call_dm_string(conn, "GetSnapshot", config_.rpc_timeout_ms, &snap_json) == AISOC_DBUS_OK) {
825	        parse_dm_snapshot_json(snap_json, &next);
826	    }
827	    if (call_dm_string(conn, "GetDeviceState", config_.rpc_timeout_ms, &state_json) == AISOC_DBUS_OK) {
828	        merge_dm_state_json(state_json, &next);
829	    }
830	    if (!next.mc.online) {
831	        McuNodeInfo fwd_mc;
832	        if (query_forward_version(conn, 1U, config_.rpc_timeout_ms, &fwd_mc)) next.mc = fwd_mc;
833	    }
834	    publish_if_changed(next, false);
835	}
