840	    AisocOtaStatus ota_snap;
841	    {
842	        std::lock_guard<std::mutex> lock(mutex_);
843	        if (!force_emit && snapshot_equal(snapshot_, next_snap)) return;
844	        snapshot_ = next_snap;
845	        cb = snapshot_cb_;
846	        ota_cb = ota_cb_;
847	        ota_snap = ota_status_;
