211	void OtaLocalOverlay::sync_from_backend() {
212	#ifdef HELIX_ENABLE_AISOC
213	    auto* conn = helix::aisoc::active_aisoc_connection();
214	    if (!conn || !subjects_initialized_) return;
215	    const auto st = conn->ota_status();
216	    const auto snap = conn->snapshot();
217	    // 同时要求 scan_state == READY、valid 与有效 SHA-256，新任务受理瞬间即同步清空旧摘要并展示 PRECHECK 在途锁。
218	    scanned_mc_sha256_ = helix::aisoc::is_ota_node_pkg_ready(st.mc) ? st.mc.sha256 : std::string();
219	    scanned_th_sha256_ = helix::aisoc::is_ota_node_pkg_ready(st.th) ? st.th.sha256 : std::string();
220	    const std::string phase_str = format_ota_phase(st);
221	    const std::string mc_str = format_ota_pkg("fw_mc.bin", st.mc);
222	    const std::string th_str = format_ota_pkg("fw_th.bin", st.th);
223	    lv_subject_copy_string(&phase_subject_, phase_str.c_str());
224	    lv_subject_copy_string(&mc_pkg_subject_, mc_str.c_str());
225	    lv_subject_copy_string(&th_pkg_subject_, th_str.c_str());
226	    lv_subject_set_int(&progress_subject_, static_cast<int32_t>(st.progress_pct));
227	    if (scan_feedback_pending_) {
228	        const auto fb = helix::aisoc::evaluate_ota_scan_feedback(pending_scan_seq_, st);
229	        if (fb != helix::aisoc::AisocScanFeedback::NONE) {
230	            scan_feedback_pending_ = false;
231	            pending_scan_seq_ = 0U;
232	            ToastSeverity sev = ToastSeverity::WARNING;
233	            if (fb == helix::aisoc::AisocScanFeedback::SUCCESS) sev = ToastSeverity::SUCCESS;
234	            else if (fb == helix::aisoc::AisocScanFeedback::ERROR) sev = ToastSeverity::ERROR;
235	            ToastManager::instance().show(sev, phase_str.c_str(), 2800);
236	        }
237	    }
238	    set_lock_hint(format_ota_lock_text(helix::aisoc::evaluate_ota_lock_state(st, snap)));
239	#endif
240	}
