219	/** @brief rt 为已锁定服务，request 为已验证指令；清理本任务计数但不伪造设备状态。 */
220	static void prepare_command(fwd_ota_runtime* rt, const fwd_ota_command_request* request) {
221	    if (rt == nullptr || request == nullptr) return;
222	    rt->operation = request->operation;
223	    rt->mask = request->target_mask;
224	    rt->reflash = request->allow_reflash;
225	    rt->task_id += 1U;
226	    rt->active = true;
227	    rt->pending = true;
228	    rt->error = "";
229	    rt->communication_error = AISOC_FWD_OK;
230	    rt->failed_node = 0U;
231	    rt->failed_command = 0U;
232	    rt->last_sequence = 0U;
233	    rt->last_elapsed_ms = 0U;
234	    for (size_t index = 0U; index < 2U; ++index) {
235	        rt->percent[index] = 0U;
236	        rt->received[index] = 0U;
237	        rt->written[index] = 0U;
238	        rt->pre_boot[index] = 0U;
239	        rt->post_boot[index] = 0U;
240	        rt->boot_session[index] = 0U;
241	        rt->warning[index][0] = '\0';
242	        std::snprintf(rt->scan_state[index], sizeof(rt->scan_state[index]), "UNSCANNED");
243	        rt->scan_error[index][0] = '\0';
244	        // 重置 scan_state 为 UNSCANNED 时同步清空旧镜像元数据，保证扫描状态、有效标志与摘要同属当次检查。
245	        if (request->operation == 0U || (request->target_mask & (1U << index)) == 0U || request->operation == 1U) {
246	            rt->image[index].valid = false;
247	            rt->image[index].size = 0U;
248	            rt->image[index].crc = 0U;
249	            rt->image[index].version = 0U;
250	            rt->image[index].sha256[0] = '\0';
251	        }
252	        const char* hash = index == 0U ? request->mc_sha256 : request->th_sha256;
253	        std::snprintf(rt->expected[index], sizeof(rt->expected[index]), "%s", hash == nullptr ? "" : hash);
254	    }
255	}
