  1	/** @file ota_image.cpp
  2	 * @brief 固定目录镜像读取与 ATSG/SHA/CRC 校验；只有 Forward 工作线程调用。
  3	 */
  4	#include "ota_internal.h"
  5	#include "firmware_hash.h"
  6	#include <cstdio>
  7	#include <cstring>
  8	#include <fcntl.h>
  9	#include <sys/stat.h>
 10	#include <unistd.h>
