104	/** @brief 清空单个镜像槽的校验有效位、大小、版本、CRC 与 SHA-256 摘要，避免失败时残留旧元数据。 */
105	static void reset_image_meta(ota_image* image) {
106	    if (image == nullptr) return;
107	    image->valid = false;
108	    image->size = 0U;
109	    image->crc = 0U;
110	    image->version = 0U;
111	    image->sha256[0] = '\0';
112	}
