114	bool ota_load_image(fwd_ota_runtime* rt, uint8_t index) {
115	    if (rt == nullptr || index > 1U) return false;
116	    auto* image = &rt->image[index];
117	    reset_image_meta(image);
118	    rt->error = "";
119	    set_scan_result(rt, index, "INVALID", "STAT_OR_SIZE_INVALID");
120	    char path[512];
121	    const char* name = index == 0U ? "fw_mc.bin" : "fw_th.bin";
122	    const int length = std::snprintf(path, sizeof(path), "%s/%s", rt->owner->firmware_dir, name);
123	    if (length < 0 || static_cast<size_t>(length) >= sizeof(path)) return false;
124	    const int fd = open(path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
125	    if (fd < 0) {
126	        // 明确区分文件不存在（MISSING）与符号链接/权限等非法文件状态（INVALID）。
127	        if (errno == ENOENT) set_scan_result(rt, index, "MISSING", "FILE_NOT_FOUND");
128	        return false;
129	    }
130	    const bool read_ok = read_image(fd, image);
131	    close(fd);
132	    if (!read_ok) {
133	        reset_image_meta(image);
134	        return false;
135	    }
136	    const char* verify_err = nullptr;
137	    if (!verify_image(image, index, &verify_err)) {
138	        reset_image_meta(image);
139	        const char* err_code = (verify_err != nullptr) ? verify_err : "TRAILER_OR_HASH_INVALID";
140	        if (std::strcmp(err_code, "PACKAGE_SIGNATURE_INVALID") == 0) {
141	            rt->error = "PACKAGE_SIGNATURE_INVALID";
142	            set_scan_result(rt, index, "SIGNATURE_INVALID", err_code);
143	        } else {
144	            set_scan_result(rt, index, "INVALID", err_code);
145	        }
146	        return false;
147	    }
148	    if (rt->operation == 1U && std::strcmp(rt->expected[index], image->sha256) != 0) {
149	        reset_image_meta(image);
150	        set_scan_result(rt, index, "INVALID", "TRAILER_OR_HASH_INVALID");
151	        return false;
152	    }
153	    set_scan_result(rt, index, "READY", "");
154	    return true;
155	}

