 320	    if (state->dds_pub_snapshot != nullptr) {
 321	        aisoc_dds_publish_temp_snapshot(state->dds_pub_snapshot, snapshot);
 322	    }
 323	    dev_dbus_emit_snapshot_updated(state, snapshot->generation_id, snapshot->timestamp_ns);
 324	    dev_dbus_emit_state_changed(
 325	        state,
 326	        old_state,
 327	        entered ? "UPGRADING_MAINTENANCE" : "IDLE",
 328	        entered ? "OTA maintenance entered" : "OTA maintenance exited");
