 331	/** @brief state为服务；有界接收Forward维护事实，在维护态跳变时同步状态机并广播快照。 */
 332	static void receive_maintenance(device_manager_state_t* state) {
 333	    if (state == nullptr || state->dds_sub_ota_status == nullptr) return;
 334	    for (size_t index = 0U; index < 4U; ++index) {
 335	        aisoc_ota_status_t status = {};
 336	        if (aisoc_dds_take_ota_status(state->dds_sub_ota_status, &status) != AISOC_DDS_OK) break;
 337	        const bool next_maint = std::strstr(status.json, "\"maintenance\":true") != nullptr;
 338	        bool changed = false;
 339	        char old_state[32] = {};
 340	        aisoc_temp_snapshot_t snapshot = {};
 341	        pthread_mutex_lock(&state->state_mutex);
 342	        if (next_maint != state->is_maintenance) {
 343	            std::snprintf(old_state, sizeof(old_state), "%s", state->device_state);
 344	            if (next_maint) dev_state_enter_maintenance(state);
 345	            else dev_state_exit_maintenance(state, false);
 346	            state->generation_id += 1U;
 347	            state->snapshot.generation_id = state->generation_id;
 348	            state->snapshot.timestamp_ns = get_host_monotonic_ns();
 349	            snapshot = state->snapshot;
 350	            changed = true;
 351	        }
 352	        pthread_mutex_unlock(&state->state_mutex);
 353	        if (changed) publish_maintenance_transition(state, &snapshot, old_state, next_maint);
 354	    }
 355	}
