 357	/** @brief state为业务主线程拥有的服务；每500ms轮转一个节点，失败只读探测不合成身份。 */
 358	static void refresh_identity(device_manager_state_t* state) {
 359	    if (state == nullptr) return;
 360	    const uint64_t now = get_host_monotonic_ns();
 361	    pthread_mutex_lock(&state->state_mutex);
 362	    const bool due = !state->is_maintenance && now >= state->next_identity_probe_ns;
 363	    const uint8_t node = state->next_identity_node == 2U ? 2U : 1U;
 364	    if (due) {
 365	        state->next_identity_probe_ns = now + 500000000ULL;
 366	        state->next_identity_node = node == 1U ? 2U : 1U;
 367	    }
 368	    pthread_mutex_unlock(&state->state_mutex);
 369	    if (due) device_manager_sync_mcu_version(state, node);
 370	}
