 284	/**
 285	 * @brief 综合双节点温度与版本在线状态更新顶层 system_status_desc 与 device_state
 286	 * @param state 设备管理服务状态结构体指针
 287	 */
 288	static void update_system_status_desc(device_manager_state_t* state) {
 289	    if (state == nullptr || state->is_fault) {
 290	        return;
 291	    }
 292	    if (state->is_maintenance) {
 293	        strncpy(state->snapshot.system_status_desc, "UPGRADING_MAINTENANCE", sizeof(state->snapshot.system_status_desc) - 1U);
 294	        strncpy(state->device_state, "UPGRADING_MAINTENANCE", sizeof(state->device_state) - 1U);
 295	        return;
 296	    }
 297	    if (state->ota_recovery_pending) {
 298	        strncpy(state->snapshot.system_status_desc, "OTA_RECOVERY_PENDING", sizeof(state->snapshot.system_status_desc) - 1U);
 299	        strncpy(state->device_state, "OTA_RECOVERY_PENDING", sizeof(state->device_state) - 1U);
 300	        return;
 301	    }
 302	    const dev_state_version_binding_t* b = find_version_binding(state);
 303	    const bool mc_offline = state->snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_OFFLINE;
 304	    const bool th_offline = state->snapshot.tool_temp_millic == AISOC_TEMP_MILLIC_OFFLINE;
 305	
 306	    if (mc_offline && th_offline) {
 307	        strncpy(state->snapshot.system_status_desc, "OFFLINE", sizeof(state->snapshot.system_status_desc) - 1U);
 308	        return;
 309	    }
 310	    if (mc_offline || th_offline) {
 311	        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
 312	        return;
 313	    }
 314	
 315	    if (!identities_ready(b)) {
 316	        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
 317	        return;
 318	    }
 319	    const bool b_fault = (state->snapshot.bed_sensor_status != (uint32_t)AISOC_SENSOR_OK) ||
 320	                         (state->snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_FAULT) ||
 321	                         (state->snapshot.bed_quality == (uint32_t)AISOC_QUALITY_FAULT);
 322	    const bool t_fault = (state->snapshot.tool_sensor_status != (uint32_t)AISOC_SENSOR_OK) ||
 323	                         (state->snapshot.tool_temp_millic == AISOC_TEMP_MILLIC_FAULT) ||
 324	                         (state->snapshot.tool_quality == (uint32_t)AISOC_QUALITY_FAULT);
 325	    if (b_fault || t_fault) {
 326	        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
 327	        return;
 328	    }
 329	    const bool b_ok = (state->snapshot.bed_sensor_status == (uint32_t)AISOC_SENSOR_OK) &&
 330	                      (state->snapshot.bed_quality == (uint32_t)AISOC_QUALITY_FRESH);
 331	    const bool t_ok = (state->snapshot.tool_sensor_status == (uint32_t)AISOC_SENSOR_OK) &&
 332	                      (state->snapshot.tool_quality == (uint32_t)AISOC_QUALITY_FRESH);
 333	    const char* desc = (b_ok && t_ok) ? "NORMAL" : "DEGRADED";
