 257	aisoc_fwd_status_t fwd_ota_command(forward_service_state_t* state,
 258	    const fwd_ota_command_request* request, uint64_t* out_task) {
 259	    if (state == nullptr || request == nullptr || out_task == nullptr) return AISOC_FWD_ERR_NULL_PTR;
 260	    if (state->ota == nullptr) return AISOC_FWD_ERR_BUSY;
 261	    if (request->operation > 1U || request->target_mask < 1U || request->target_mask > 3U)
 262	        return AISOC_FWD_ERR_INVALID_ARG;
 263	    if (request->operation == 1U) {
 264	        if (!request->confirmed_safe) return AISOC_FWD_ERR_INVALID_ARG;
 265	        if ((request->target_mask & 1U) != 0U && !valid_hash(request->mc_sha256)) return AISOC_FWD_ERR_INVALID_ARG;
 266	        if ((request->target_mask & 2U) != 0U && !valid_hash(request->th_sha256)) return AISOC_FWD_ERR_INVALID_ARG;
 267	    }
 268	    auto* rt = state->ota;
 269	    pthread_mutex_lock(&rt->mutex);
 270	    if (rt->active || rt->stopping) {
 271	        pthread_mutex_unlock(&rt->mutex);
 272	        return AISOC_FWD_ERR_BUSY;
 273	    }
 274	    prepare_command(rt, request);
 275	    *out_task = rt->task_id;
 276	    pthread_cond_broadcast(&rt->wake);
 277	    pthread_mutex_unlock(&rt->mutex);
 278	    return AISOC_FWD_OK;
 279	}
