 878	AisocOtaGateVerdict check_ota_scan_gate(bool has_conn, const AisocOtaStatus& st, const AisocSnapshot& snap) {
 879	    if (!has_conn) return AisocOtaGateVerdict::DISCONNECTED;
 880	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
 881	    if (st.active || (snap.maintenance_locked && !mc_recovery)) {
 882	        return AisocOtaGateVerdict::BACKEND_BUSY;
 883	    }
 884	    return AisocOtaGateVerdict::ALLOW;
 885	}
