 887	AisocOtaGateVerdict check_ota_upgrade_gate(uint8_t mask, bool confirmed_safe,
 888	                                           const AisocOtaStatus& st, const AisocSnapshot& snap) {
 889	    if (mask == 0U || !confirmed_safe) return AisocOtaGateVerdict::MISSING_SELECTION;
 890	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
 891	    if (st.active || (snap.maintenance_locked && !mc_recovery)) {
 892	        return AisocOtaGateVerdict::BACKEND_BUSY;
 893	    }
 894	    if (mc_recovery && mask != 1U) return AisocOtaGateVerdict::MC_RECOVERY_ONLY;
 895	    const bool mc_ready = ((mask & 1U) == 0U) || is_ota_node_pkg_ready(st.mc);
 896	    const bool th_ready = ((mask & 2U) == 0U) || is_ota_node_pkg_ready(st.th);
 897	    if (!mc_ready || !th_ready) return AisocOtaGateVerdict::PACKAGE_NOT_READY;
 898	    if (!snap.dm_connected) return AisocOtaGateVerdict::DISCONNECTED;
 899	    // MC 待恢复单选升级允许通过串口直接刷回 App，不因 DM 暂报 MC 离线阻断恢复。
 900	    const bool mc_online = ((mask & 1U) == 0U) || snap.mc.online || mc_recovery;
 901	    const bool th_online = ((mask & 2U) == 0U) || snap.th.online;
 902	    if (!mc_online || !th_online) return AisocOtaGateVerdict::NODE_OFFLINE;
 903	    return AisocOtaGateVerdict::ALLOW;
 904	}
