 906	AisocScanFeedback evaluate_ota_scan_feedback(uint64_t pending_scan_seq, const AisocOtaStatus& st) {
 907	    if (pending_scan_seq == 0U || st.client_req_seq != pending_scan_seq) {
 908	        return AisocScanFeedback::NONE;
 909	    }
 910	    if (st.last_rpc_code < 0) {
 911	        return (st.error == "RPC_DISCONNECTED") ? AisocScanFeedback::ERROR : AisocScanFeedback::WARNING;
 912	    }
 913	    const bool scan_done = (!st.active) && (st.phase == "READY" || st.phase == "FAILED");
 914	    if (!scan_done) return AisocScanFeedback::NONE;
 915	    return (st.phase == "READY") ? AisocScanFeedback::SUCCESS : AisocScanFeedback::WARNING;
 916	}
