 918	AisocOtaLockState evaluate_ota_lock_state(const AisocOtaStatus& st, const AisocSnapshot& snap) {
 919	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
 920	    const bool busy = st.active || (st.last_rpc_code == -5) || (snap.maintenance_locked && !mc_recovery);
 921	    if (busy) return AisocOtaLockState::BUSY;
 922	    if (snap.estop_confirmed) return AisocOtaLockState::ESTOP_CONFIRMED;
 923	    if (snap.estop_latched) return AisocOtaLockState::ESTOP_LATCHED_UNCONFIRMED;
 924	    if (!snap.dm_connected) return AisocOtaLockState::DISCONNECTED;
 925	    if (mc_recovery) return AisocOtaLockState::MC_RECOVERY;
 926	    if (!snap.mc.online || !snap.th.online) return AisocOtaLockState::NODE_OFFLINE;
 927	    return AisocOtaLockState::READY;
 928	}
