   242	void OtaLocalOverlay::handle_scan() {
   243	#ifdef HELIX_ENABLE_AISOC
   244	    auto* conn = helix::aisoc::active_aisoc_connection();
   245	    const auto st = conn ? conn->ota_status() : helix::aisoc::AisocOtaStatus{};
   246	    const auto snap = conn ? conn->snapshot() : helix::aisoc::AisocSnapshot{};
   247	    const auto verdict = helix::aisoc::check_ota_scan_gate(conn != nullptr, st, snap);
   248	    if (verdict == helix::aisoc::AisocOtaGateVerdict::DISCONNECTED) {
   249	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
   250	        return;
   251	    }
   252	    if (verdict == helix::aisoc::AisocOtaGateVerdict::BACKEND_BUSY) {
   253	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
   254	        return;
   255	    }
   256	    helix::aisoc::AisocOtaRequest req;
   257	    req.operation = 0U;
   258	    req.target_mask = 3U;
   259	    pending_scan_seq_ = conn->request_ota(req);
   260	    scan_feedback_pending_ = (pending_scan_seq_ != 0U);
   261	#endif
   262	}
