   264	void OtaLocalOverlay::handle_start_upgrade() {
   265	#ifdef HELIX_ENABLE_AISOC
   266	    auto* conn = helix::aisoc::active_aisoc_connection();
   267	    if (!conn) {
   268	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
   269	        return;
   270	    }
   271	    const uint8_t mask = static_cast<uint8_t>((select_mc_ ? 1U : 0U) | (select_th_ ? 2U : 0U));
   272	    const auto st = conn->ota_status();
   273	    const auto snap = conn->snapshot();
   274	    const auto verdict = helix::aisoc::check_ota_upgrade_gate(mask, confirmed_safe_, st, snap);
   275	    if (verdict == helix::aisoc::AisocOtaGateVerdict::MISSING_SELECTION) {
   276	        ToastManager::instance().show(ToastSeverity::WARNING, "请选择升级节点并开启安全前置确认", 2500);
   277	        return;
   278	    }
   279	    if (verdict == helix::aisoc::AisocOtaGateVerdict::BACKEND_BUSY) {
   280	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
   281	        return;
   282	    }
   283	    if (verdict == helix::aisoc::AisocOtaGateVerdict::MC_RECOVERY_ONLY) {
   284	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC", 2800);
   285	        return;
   286	    }
   287	    if (verdict == helix::aisoc::AisocOtaGateVerdict::PACKAGE_NOT_READY) {
   288	        ToastManager::instance().show(ToastSeverity::WARNING, "请先扫描固件并确认所选节点固件包校验通过", 2500);
   289	        return;
   290	    }
   291	    if (verdict == helix::aisoc::AisocOtaGateVerdict::DISCONNECTED) {
   292	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
   293	        return;
   294	    }
   295	    if (verdict == helix::aisoc::AisocOtaGateVerdict::NODE_OFFLINE) {
   296	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）", 2500);
   297	        return;
   298	    }
   299	    scan_feedback_pending_ = false;
   300	    pending_scan_seq_ = 0U;
   301	    helix::aisoc::AisocOtaRequest req;
   302	    req.operation = 1U;
   303	    req.target_mask = mask;
   304	    req.confirmed_safe = true;
   305	    req.allow_reflash = allow_reflash_;
   306	    req.mc_sha256 = ((mask & 1U) != 0U) ? st.mc.sha256 : std::string();
   307	    req.th_sha256 = ((mask & 2U) != 0U) ? st.th.sha256 : std::string();
   308	    (void)conn->request_ota(req);
   309	#endif
   310	}
