291	    if (verdict == helix::aisoc::AisocOtaGateVerdict::DISCONNECTED) {
292	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
293	        return;
294	    }
