/** @brief 格式化单颗 MCU 固定目录固件扫描状态、包信息与明确下一步提示。 */
static std::string format_ota_pkg(const char* label, const helix::aisoc::AisocOtaNodeInfo& info) {
    const char* name = (info.file.empty() && label != nullptr) ? label : info.file.c_str();
    if (helix::aisoc::is_ota_node_pkg_ready(info)) {
        char buf[160] = {};
        std::snprintf(buf, sizeof(buf), "已就绪 · %s (%uB, sha:%s..)",
                      name, info.size, info.sha256.substr(0, 12).c_str());
        return std::string(buf);
    }
    if (info.scan_state == "MISSING") {
        const char* target = (label != nullptr) ? label : name;
        return std::string("缺失 · 未找到 ") + target +
               "（请放入 /run/printer-soc/firmware/ 后重扫，或取消选择该板）";
    }
    if (info.scan_state == "SIGNATURE_INVALID") {
        return "校验失败 · 发布签名校验未通过（请替换有效签名包后重扫）";
    }
    if (info.scan_state == "INVALID") {
        return "校验失败 · 包完整性或板型不匹配（请替换有效包后重扫）";
    }
    return std::string(label != nullptr ? label : "firmware.bin") + ": 未扫描（点击下方扫描）";
}

