static aisoc_dbus_status_t handle_emergency_stop(
    const aisoc_dbus_msg_t* req,
    aisoc_dbus_msg_t* reply,
    void* user_data
) {
    if (req == nullptr || reply == nullptr || user_data == nullptr) {
        return AISOC_DBUS_ERR_NULL_PTR;
    }
    forward_service_state_t* state = (forward_service_state_t*)user_data;

    aisoc_dbus_iter_t iter;
    aisoc_dbus_iter_init(req, &iter);
    uint8_t reason_code = 0U;
    aisoc_dbus_iter_get_byte(&iter, &reason_code);

    const aisoc_fwd_status_t st = forward_service_emergency_stop(state, reason_code);
    const int32_t err = (st == AISOC_FWD_OK) ? 0 : (int32_t)st;
    aisoc_dbus_msg_append_int32(reply, err);
    aisoc_dbus_msg_append_string(reply, state->last_fault.detail);
    return AISOC_DBUS_OK;
}

